pub static COMPANION_BOOKS: crate::rules_core::rules_catalog::Derived<CompanionBook> =
    crate::rules_core::rules_catalog::Derived::new(companion_books_from_package);

fn companion_books_from_package() -> Vec<CompanionBook> {
    use crate::rules_core::rules_catalog::rows;
    use crate::rules_core::rules_data_package::CompanionBookIndexRow;
    rows::<CompanionBookIndexRow>("companion_chassis/COMPANION_BOOKS")
        .iter()
        .map(|book| CompanionBook {
            corpus_book: book.corpus_book,
            companions: if book.companions.is_empty() {
                &[]
            } else {
                rows::<CompanionRecord>(book.companions)
            },
            companion_abilities: if book.companion_abilities.is_empty() {
                &[]
            } else {
                rows::<CompanionAbilityRecord>(book.companion_abilities)
            },
            companion_classes: if book.companion_classes.is_empty() {
                &[]
            } else {
                rows::<CompanionClassRecord>(book.companion_classes)
            },
        })
        .collect()
}
// COMPANION_BOOK_REGISTRY: the Pathfinder book list is COMPANION_BOOKS (package-backed); no other system registers a companion book yet.;
pub fn companion_book(corpus_book: &str) -> Option<&'static CompanionBook> {
    COMPANION_BOOKS
        .iter()
        .find(|book| book.corpus_book == corpus_book)
}
